//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_number` previous retries.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        self.base_delay_ms
            .saturating_mul(2u64.saturating_pow(retry_number))
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_growth_saturates_at_the_configured_maximum() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(1), 20);
        assert_eq!(config.delay_for_retry(2), 25);
        assert_eq!(config.delay_for_retry(3), 25);
    }

    #[test]
    fn delay_calculation_is_safe_for_large_values() {
        let config = RetryConfig {
            max_attempts: 3,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(1), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // Attempt one is always made, even when the configured budget is invalid.
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt - 1));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};
    use std::cell::Cell;

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();

        let result = run_job(&config(5), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Transient("temporary outage".into()))
        });

        assert_eq!(
            result,
            Err(RetryError::Transient("temporary outage".into()))
        );
        assert_eq!(calls.get(), 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();

        let result = run_job(&config(5), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls.get(), 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_budget_includes_the_first_call_and_stops_after_success() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();

        let result = run_job(&config(3), &mut sleeper, || {
            calls.set(calls.get() + 1);
            if calls.get() == 3 {
                Ok(())
            } else {
                Err(RetryError::Transient("try again".into()))
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls.get(), 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_until_success() {
    let mut attempts = 0;
    let mut sleeper = FakeSleeper::default();
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        if attempts == 4 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary".to_string()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 4);
    assert_eq!(sleeper.sleeps, vec![5, 8, 8]);
}

#[test]
fn public_api_returns_permanent_errors_without_retrying() {
    let mut attempts = 0;
    let mut sleeper = FakeSleeper::default();
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Permanent("invalid request".to_string()))
    });

    assert_eq!(
        result,
        Err(RetryError::Permanent("invalid request".to_string()))
    );
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}
